settings.custom_css:
/* ===== Don Carlo · diseño fuego (kit global) ===== */
:root{--dc-bg:#0E0A08;--dc-s1:#1A1310;--dc-s2:#251A15;--dc-line:rgba(220,120,100,.14);--dc-fire:#D4452A;--dc-ember:#A3172C;--dc-amber:#EFA54E;--dc-cream:#F7EEE3;--dc-txt:#E9DCCD;--dc-muted:#BFAE9F;--dc-basil:#4F9D50;--dc-grad:linear-gradient(135deg,#E0662E 0%,#B8202F 52%,#7A1022 100%);--dc-granate:#8C1427;--dc-r:18px;--dc-shadow:0 18px 40px -18px rgba(150,18,36,.45)}
body{background:var(--dc-bg)!important;background-image:radial-gradient(1200px 600px at 85% -10%,rgba(178,28,44,.10),transparent 60%),radial-gradient(900px 500px at -10% 30%,rgba(122,16,34,.07),transparent 60%)!important;background-attachment:fixed!important;color:var(--dc-txt);font-family:"DM Sans",system-ui,sans-serif}
h1,h2,h3,h4,.elementor-heading-title{font-family:"Bricolage Grotesque",system-ui,sans-serif}
::selection{background:var(--dc-fire);color:#fff}
.dc-wrap{max-width:1200px;margin:0 auto;width:100%;padding:0 3em!important}
@media(max-width:1024px){.dc-wrap{padding:0 2em!important}}
@media(max-width:767px){.dc-wrap{padding:0 1em!important}}
.dc-sec{padding:5em 0!important}
@media(max-width:767px){.dc-sec{padding:3.2em 0!important}}
.dc-center,.dc-center .elementor-heading-title{text-align:center}
.dc-center-row{flex-direction:row!important;justify-content:center;margin-top:2.2em}
/* tipos */
.dc-eyebrow p,.dc-eyebrow{margin:0 0 .6em;font:700 .78rem/1.2 "DM Sans",sans-serif;letter-spacing:.22em;text-transform:uppercase;color:var(--dc-amber)}
.dc-h1 .elementor-heading-title{font-size:clamp(2.4rem,5.4vw,4.6rem);line-height:1.02;font-weight:800;color:var(--dc-cream);letter-spacing:-.01em}
.dc-h1 em,.dc-h2 em{font-style:normal;background:var(--dc-grad);-webkit-background-clip:text;background-clip:text;color:transparent}
.dc-h2 .elementor-heading-title{font-size:clamp(1.9rem,3.6vw,3rem);line-height:1.1;font-weight:800;color:var(--dc-cream);margin-bottom:.9em}
.dc-h3 .elementor-heading-title{font-size:1.7rem;line-height:1.15;color:var(--dc-cream);font-weight:800;margin:.2em 0 .7em}
.dc-h4 .elementor-heading-title{font-size:1.3rem;color:var(--dc-cream);font-weight:700;margin:.5em 0 .4em}
.dc-lead p,.dc-lead{font-size:1.15rem;line-height:1.6;color:var(--dc-txt);max-width:34em;margin:1.1em 0 0}
.dc-lead a,.dc-list a{color:var(--dc-amber);font-weight:700;text-decoration:none}
.dc-p p{color:var(--dc-muted);line-height:1.6;margin:0}
/* botones */
.dc-btn .elementor-button{display:inline-flex;align-items:center;gap:.2em;border-radius:999px!important;padding:1em 1.7em!important;font:700 1rem/1 "DM Sans",sans-serif!important;letter-spacing:.02em;transition:transform .2s ease,box-shadow .2s ease,background .2s ease;border:0}
.dc-btn--fire .elementor-button{background:var(--dc-grad)!important;color:#fff!important;box-shadow:var(--dc-shadow),inset 0 1px 0 rgba(255,255,255,.35)}
.dc-btn--fire .elementor-button:hover{transform:translateY(-2px) scale(1.02);box-shadow:0 22px 44px -14px rgba(150,18,36,.7),inset 0 1px 0 rgba(255,255,255,.35)}
.dc-btn--ghost .elementor-button{background:rgba(255,255,255,.04)!important;color:var(--dc-cream)!important;border:1.5px solid rgba(239,165,78,.45)!important}
.dc-btn--ghost .elementor-button:hover{background:rgba(239,165,78,.12)!important;border-color:var(--dc-amber)!important}
.dc-btn--link .elementor-button{background:transparent!important;color:var(--dc-amber)!important;padding-left:.4em!important}
.dc-btn--xl .elementor-button{font-size:1.15rem!important;padding:1.15em 2.2em!important}
.dc-ctas{flex-direction:row!important;flex-wrap:wrap;gap:.8em!important;margin-top:1.8em}
/* chips */
.dc-chips{list-style:none;margin:1.6em 0 0;padding:0;display:flex;flex-wrap:wrap;gap:.5em}
.dc-chips li{padding:.5em .95em;border-radius:999px;background:rgba(255,255,255,.05);border:1px solid var(--dc-line);font-size:.88rem;color:var(--dc-txt)}
/* HERO */
.dc-hero{position:relative;overflow:hidden;padding:4.5em 0 3em!important;background:radial-gradient(700px 500px at 75% 50%,rgba(178,28,44,.28),transparent 65%),radial-gradient(500px 400px at 70% 80%,rgba(122,16,34,.22),transparent 70%)}
.dc-hero__in{flex-direction:row!important;align-items:center;gap:2em!important}
.dc-hero__txt{flex:1 1 52%;min-width:0}
.dc-hero__media{flex:1 1 48%;position:relative;align-items:center;justify-content:center;min-height:420px}
.dc-hero__pizza{position:relative;z-index:2;width:100%;max-width:560px;margin:0 auto}
.dc-hero__pizza img{width:100%;height:auto;filter:drop-shadow(0 30px 50px rgba(0,0,0,.65)) drop-shadow(0 0 60px rgba(178,28,44,.35));animation:dcSpin 60s linear infinite}
@keyframes dcSpin{to{transform:rotate(360deg)}}
.dc-glow{position:absolute!important;inset:0;z-index:1;pointer-events:none}
.dc-glow__ring{position:absolute;left:50%;top:50%;width:92%;aspect-ratio:1;transform:translate(-50%,-50%);border-radius:50%;background:radial-gradient(circle,rgba(200,62,42,.45) 0%,rgba(122,16,34,.18) 45%,transparent 70%);filter:blur(10px);animation:dcPulse 4s ease-in-out infinite}
@keyframes dcPulse{0%,100%{opacity:.75;transform:translate(-50%,-50%) scale(.97)}50%{opacity:1;transform:translate(-50%,-50%) scale(1.04)}}
@media(prefers-reduced-motion:reduce){.dc-hero__pizza img,.dc-glow__ring{animation:none}}
.dc-tri{display:flex;width:120px;height:4px;margin:3em auto 0;border-radius:4px;overflow:hidden}
.dc-tri i{flex:1}.dc-tri i:nth-child(1){background:#2E8B3E}.dc-tri i:nth-child(2){background:#F4EFE6}.dc-tri i:nth-child(3){background:#A3172C}
@media(max-width:767px){.dc-hero{padding:2.2em 0 2em!important}.dc-hero__in{flex-direction:column-reverse!important;gap:.5em!important}.dc-hero__media{min-height:0;width:100%}.dc-hero__pizza{max-width:300px}.dc-hero__txt{text-align:center}.dc-lead p{margin-left:auto;margin-right:auto}.dc-ctas{justify-content:center}.dc-ctas .elementor-widget-button{flex:1 1 100%}.dc-ctas .elementor-button{width:100%;justify-content:center}.dc-chips{justify-content:center}}
/* tarjetas locales */
.dc-grid2{flex-direction:row!important;gap:1.5em!important;margin-top:.5em}
.dc-grid2>.e-con{flex:1 1 0}
@media(max-width:767px){.dc-grid2{flex-direction:column!important}}
.dc-card{background:linear-gradient(180deg,var(--dc-s2),var(--dc-s1));border:1px solid var(--dc-line);border-radius:var(--dc-r);padding:2.2em!important;position:relative;overflow:hidden}
.dc-card--fire{border-color:rgba(178,28,44,.45);box-shadow:var(--dc-shadow)}
.dc-card--fire:before{content:"";position:absolute;right:-80px;top:-80px;width:240px;height:240px;border-radius:50%;background:radial-gradient(circle,rgba(178,28,44,.35),transparent 70%)}
.dc-tag p{display:inline-block;margin:0;padding:.35em .8em;border-radius:999px;background:rgba(178,28,44,.15);color:var(--dc-amber);font-weight:700;font-size:.75rem;letter-spacing:.14em;text-transform:uppercase}
.dc-tag--basil p{background:rgba(79,157,80,.16);color:#8FD08F}
.dc-list{list-style:none;margin:0 0 1.6em;padding:0}
.dc-list li{padding:.6em 0 .6em 1.6em;border-bottom:1px dashed var(--dc-line);position:relative;color:var(--dc-txt)}
.dc-list li:before{content:"";position:absolute;left:0;top:1.05em;width:8px;height:8px;border-radius:50%;background:var(--dc-grad)}
.dc-list b{color:var(--dc-cream)}
/* features */
.dc-grid3{flex-direction:row!important;gap:1.5em!important}
.dc-grid3>.e-con{flex:1 1 0}
@media(max-width:767px){.dc-grid3{flex-direction:column!important}}
.dc-feat{padding:1.8em!important;border-radius:var(--dc-r);background:rgba(255,255,255,.025);border:1px solid var(--dc-line);text-align:center;align-items:center}
.dc-ico span{display:inline-grid;place-items:center;width:64px;height:64px;border-radius:50%;font-size:1.8rem;background:radial-gradient(circle,rgba(178,28,44,.35),rgba(178,28,44,.05));box-shadow:0 0 0 1px rgba(178,28,44,.3)}
/* CTA final */
.dc-cta__in{text-align:center;align-items:center;padding:3.5em 2em!important;border-radius:28px;background:radial-gradient(600px 300px at 50% 120%,rgba(178,28,44,.45),transparent 70%),var(--dc-s1);border:1px solid rgba(178,28,44,.35)}
.dc-cta__in .dc-lead p{margin:0 auto}
@media(max-width:767px){.dc-cta__in{padding:2.5em 1.2em!important}}

/* ===== Tarjeta de producto (listado JetEngine 2618) ===== */
.dc-pcard{height:100%;background:linear-gradient(180deg,var(--dc-s2),var(--dc-s1));border:1px solid var(--dc-line);border-radius:var(--dc-r);overflow:hidden;transition:transform .25s ease,box-shadow .25s ease,border-color .25s ease}
.dc-pcard:hover{transform:translateY(-6px);border-color:rgba(178,28,44,.55);box-shadow:0 26px 50px -22px rgba(150,18,36,.6)}
.dc-pcard__media{position:relative;overflow:hidden;aspect-ratio:4/3;background:#120d0a}
.dc-pcard__media:after{content:"";position:absolute;inset:auto 0 0 0;height:40%;background:linear-gradient(0deg,rgba(26,19,16,.95),transparent);pointer-events:none}
.dc-pcard__img,.dc-pcard__img .elementor-widget-container,.dc-pcard__img a{height:100%}
.dc-pcard__img img{width:100%!important;height:100%!important;object-fit:cover;transition:transform .6s ease;display:block}
.dc-pcard:hover .dc-pcard__img img{transform:scale(1.07) rotate(-2deg)}
.dc-pcard__body{padding:1.1em 1.3em 1.3em!important;flex:1 1 auto;gap:.3em!important}
.dc-pcard__title .elementor-heading-title{font-size:1.45rem;font-weight:800;color:var(--dc-cream);margin:0}
.dc-pcard__title a{color:inherit!important}
.dc-pcard__desc{flex:1 1 auto}
.dc-pcard__desc p,.dc-pcard__desc{color:var(--dc-muted);font-size:.95rem;line-height:1.45;margin:0}
.dc-pcard__foot{flex-direction:row!important;align-items:center;justify-content:space-between;gap:.6em!important;margin-top:1em;padding-top:1em;border-top:1px dashed var(--dc-line)}
.dc-pcard__price,.dc-pcard__price p{margin:0;font:800 1.6rem/1 "Bricolage Grotesque",sans-serif;color:var(--dc-amber)}
.dc-pcard__price .woocommerce-Price-currencySymbol{font-size:.7em;margin-left:.1em}
.dc-pcard__price del{opacity:.5;font-size:.6em;margin-right:.3em}.dc-pcard__price ins{text-decoration:none}
.dc-pcard__btn .elementor-button{padding:.8em 1.2em!important;font-size:.92rem!important}
.dc-grid-pizzas .jet-listing-grid__items{--columns:3}
@media(max-width:767px){.dc-pcard__title .elementor-heading-title{font-size:1.3rem}.dc-pcard__price,.dc-pcard__price p{font-size:1.4rem}}
.jet-listing-grid__item{padding:10px!important}

/* ===== Arreglo móvil: contenedores propios siempre en columna ===== */
.dc-card,.dc-feat,.dc-pcard,.dc-pcard__body,.dc-phead,.dc-product__info,.dc-product__media,.dc-sec,.dc-catnav-wrap{flex-direction:column!important}
.dc-wrap>.elementor-widget,.dc-card>.elementor-widget,.dc-feat>.elementor-widget{width:100%}
html,body{overflow-x:clip}

/* ===== Cabecera de página de carta ===== */
.dc-phead{padding:3.6em 0 1.4em!important;position:relative;background:radial-gradient(700px 320px at 50% 0%,rgba(178,28,44,.22),transparent 70%)}
.dc-phead .dc-wrap{align-items:center;text-align:center}
.dc-phead .elementor-heading-title{text-align:center}
.dc-h1--page .elementor-heading-title{font-size:clamp(2.2rem,5vw,3.8rem)}
.dc-phead .dc-lead p{margin:1em auto 0;text-align:center}
.dc-chips--info{justify-content:center}
.dc-chips--info li{background:rgba(178,28,44,.08);border-color:rgba(178,28,44,.25)}
.dc-mataro p{margin:1.1em 0 0;text-align:center;font-size:.92rem;color:var(--dc-muted)}
.dc-mataro a{color:var(--dc-amber);font-weight:700;text-decoration:none}
@media(max-width:767px){.dc-phead{padding:2.2em 0 1em!important}.dc-chips--info li{font-size:.8rem;padding:.45em .8em}}

/* ===== Barra de categorías ===== */
.dc-catnav-wrap{position:sticky;top:0;z-index:50;padding:.7em 0!important;background:rgba(14,10,8,.82);-webkit-backdrop-filter:blur(12px);backdrop-filter:blur(12px);border-bottom:1px solid var(--dc-line)}
.dc-catnav{display:flex;gap:.5em;justify-content:center;overflow-x:auto;scrollbar-width:none;-webkit-overflow-scrolling:touch}
.dc-catnav::-webkit-scrollbar{display:none}
.dc-catnav__a{flex:0 0 auto;display:inline-flex;align-items:center;gap:.45em;padding:.62em 1.15em;border-radius:999px;border:1px solid var(--dc-line);background:rgba(255,255,255,.04);color:var(--dc-txt)!important;font:700 .95rem/1 "DM Sans",sans-serif;text-decoration:none!important;transition:all .2s ease;white-space:nowrap}
.dc-catnav__a:hover{border-color:rgba(239,165,78,.6);color:var(--dc-cream)!important}
.dc-catnav__a.is-active{background:var(--dc-grad);border-color:transparent;color:#fff!important;box-shadow:0 10px 24px -10px rgba(150,18,36,.7)}
@media(max-width:767px){.dc-catnav{justify-content:flex-start}.dc-catnav__a{font-size:.88rem;padding:.58em .95em}}
.dc-sec--grid{padding-top:2.4em!important}
.dc-catnav-wrap .dc-catnav{margin:0}

/* ===== Tarjeta bebida ===== */
.dc-pcard--drink .dc-pcard__media--drink{aspect-ratio:1/1;background:radial-gradient(circle at 50% 60%,rgba(178,28,44,.22),transparent 65%),#140e0b;padding:1.2em}
.dc-pcard--drink .dc-pcard__media--drink:after{display:none}
.dc-pcard--drink .dc-pcard__img img{object-fit:contain!important;filter:drop-shadow(0 14px 18px rgba(0,0,0,.55))}
.dc-pcard--drink:hover .dc-pcard__img img{transform:scale(1.06)}
.dc-pcard--drink .dc-pcard__title .elementor-heading-title{font-size:1.12rem;line-height:1.2}
.dc-pcard--drink .dc-pcard__price,.dc-pcard--drink .dc-pcard__price p{font-size:1.3rem}
.dc-pcard--drink .dc-pcard__foot{flex-direction:column!important;align-items:stretch}
.dc-atc .jet-woo-builder-archive-add-to-cart,.dc-atc form.cart,.dc-atc .cart{display:flex;gap:.5em;align-items:center;margin:0}
.dc-atc .quantity input.qty{width:3.6em;height:2.8em;border-radius:999px;border:1px solid var(--dc-line);background:rgba(255,255,255,.05);color:var(--dc-cream);text-align:center;font-weight:700}
.dc-atc .button,.dc-atc a.button,.dc-atc button{flex:1 1 auto;display:inline-flex!important;justify-content:center;align-items:center;min-height:2.8em;border-radius:999px!important;border:0!important;background:var(--dc-grad)!important;color:#fff!important;font:700 .92rem/1 "DM Sans",sans-serif!important;padding:.8em 1em!important;box-shadow:0 12px 26px -12px rgba(150,18,36,.7);transition:transform .2s ease}
.dc-atc .button:hover{transform:translateY(-2px)}
.dc-atc .added_to_cart{display:none!important}
.dc-atc .button.loading{opacity:.7}
.dc-atc .button.added:after{content:" ✓";margin-left:.3em}
.dc-grid-drinks .jet-listing-grid__item{padding:8px!important}
@media(max-width:767px){.dc-pcard--drink .dc-pcard__body{padding:.8em .9em 1em!important}.dc-pcard--drink .dc-pcard__title .elementor-heading-title{font-size:1rem}.dc-atc .button{font-size:.85rem!important}}

/* ===== Ficha de producto ===== */
.dc-product{padding-top:2.6em!important}
.dc-product__grid{flex-direction:row!important;gap:3.5em!important;align-items:flex-start}
.dc-product__media{flex:1 1 46%;position:sticky!important;top:5em;align-items:center;justify-content:center;min-height:380px;min-width:0}
.dc-product__img{position:relative;z-index:2;width:100%}
.dc-product__img img{width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:50%;box-shadow:0 40px 80px -30px rgba(0,0,0,.9),0 0 0 6px rgba(178,28,44,.18),0 0 80px rgba(178,28,44,.35)}
.dc-product__info{flex:1 1 54%;min-width:0}
.dc-h1--product .elementor-heading-title{font-size:clamp(2.3rem,4.6vw,3.8rem)}
.dc-ingr-label p,.dc-extras-label p{margin:1.4em 0 .4em;font:700 .76rem/1 "DM Sans",sans-serif;letter-spacing:.2em;text-transform:uppercase;color:var(--dc-muted)}
.dc-ingr,.dc-ingr p,.dc-ingr .woocommerce-product-details__short-description{font-size:1.12rem;line-height:1.6;color:var(--dc-txt);margin:0}
.dc-price .price,.dc-price p,.dc-price{margin:.5em 0 0!important;font:800 2.6rem/1 "Bricolage Grotesque",sans-serif!important;background:var(--dc-grad);-webkit-background-clip:text;background-clip:text;color:transparent!important}
.dc-price .price *{color:inherit!important;-webkit-text-fill-color:transparent}
.dc-price del{opacity:.5;font-size:.55em}.dc-price ins{text-decoration:none}
/* Formulario Product Add-ons */
.dc-addtocart form.cart{margin:0!important}
.dc-addtocart .wc-pao-addons-container{margin:0 0 1.2em}
.dc-addtocart .wc-pao-addon{margin:0 0 1em!important;padding:1.1em 1.2em!important;border-radius:var(--dc-r);background:rgba(255,255,255,.03);border:1px solid var(--dc-line)}
.dc-addtocart .wc-pao-addon-name,.dc-addtocart .wc-pao-addon .wc-pao-addon-name{display:block;margin:0 0 .7em;font:700 1.05rem/1.2 "DM Sans",sans-serif;color:var(--dc-cream)}
.dc-addtocart .wc-pao-addon-description,.dc-addtocart .wc-pao-addon-description p{color:var(--dc-muted);font-size:.9rem;margin:0 0 .6em}
.dc-addtocart .wc-pao-addon-wrap{margin:0}
.dc-addtocart .wc-pao-addon-checkbox-group,.dc-addtocart .wc-pao-addon-radio-group{display:flex;flex-wrap:wrap;gap:.45em}
.dc-addtocart .wc-pao-addon-wrap p.form-row,.dc-addtocart .wc-pao-addon .form-row{margin:0!important;padding:0!important;width:auto!important;float:none!important}
.dc-addtocart .wc-pao-addon label{display:inline-flex;align-items:center;gap:.45em;padding:.5em .85em;border-radius:999px;border:1px solid var(--dc-line);background:rgba(255,255,255,.04);color:var(--dc-txt);font-size:.9rem;cursor:pointer;transition:all .15s ease;margin:0}
.dc-addtocart .wc-pao-addon label:hover{border-color:rgba(239,165,78,.55)}
.dc-addtocart .wc-pao-addon label:has(input:checked){background:rgba(178,28,44,.18);border-color:var(--dc-fire);color:var(--dc-cream)}
.dc-addtocart .wc-pao-addon input[type=checkbox],.dc-addtocart .wc-pao-addon input[type=radio]{accent-color:var(--dc-fire);width:1.05em;height:1.05em;margin:0}
.dc-addtocart .wc-pao-addon .wc-pao-addon-price{color:var(--dc-amber);font-weight:700}
.dc-addtocart select,.dc-addtocart textarea,.dc-addtocart input[type=text],.dc-addtocart input[type=number]{width:100%;border-radius:12px;border:1px solid var(--dc-line);background:#120d0a;color:var(--dc-cream);padding:.75em 1em}
.dc-addtocart .product-addon-totals,.dc-addtocart #product-addons-total{margin:1em 0!important;padding:1em 1.2em!important;border-radius:var(--dc-r);background:rgba(178,28,44,.07);border:1px dashed rgba(178,28,44,.35);color:var(--dc-txt)}
.dc-addtocart .product-addon-totals ul{margin:0;padding:0;list-style:none}
.dc-addtocart .product-addon-totals li{display:flex;justify-content:space-between;gap:1em;border:0!important;padding:.25em 0!important}
.dc-addtocart .product-addon-totals .wc-pao-subtotal-line{border-top:1px dashed var(--dc-line)!important;margin-top:.4em;padding-top:.6em!important}
.dc-addtocart .product-addon-totals .wc-pao-subtotal-line .price,.dc-addtocart .product-addon-totals .amount{color:var(--dc-amber);font-weight:800}
.dc-addtocart .quantity{display:inline-flex}
.dc-addtocart .quantity input.qty{width:4em;height:3.6em;border-radius:999px;border:1px solid var(--dc-line);background:rgba(255,255,255,.05);color:var(--dc-cream);text-align:center;font-weight:800;font-size:1.05rem}
.dc-addtocart form.cart:not(.variations_form)>div:last-child,.dc-addtocart form.cart{display:flex;flex-wrap:wrap;gap:.7em;align-items:center}
.dc-addtocart .wc-pao-addons-container,.dc-addtocart .product-addon-totals{flex:1 1 100%}
.dc-addtocart .single_add_to_cart_button{flex:1 1 auto;min-height:3.6em;border-radius:999px!important;border:0!important;background:var(--dc-grad)!important;color:#fff!important;font:800 1.12rem/1 "DM Sans",sans-serif!important;letter-spacing:.02em;padding:1em 2em!important;box-shadow:0 18px 40px -14px rgba(150,18,36,.8),inset 0 1px 0 rgba(255,255,255,.35);transition:transform .2s ease,box-shadow .2s ease;animation:dcGlowBtn 3s ease-in-out infinite}
.dc-addtocart .single_add_to_cart_button:before{content:"🛒 ";}
.dc-addtocart .single_add_to_cart_button:hover{transform:translateY(-2px) scale(1.01)}
