.dc-menu__tile .elementor-icon-box-icon{margin:0 0 .55em!important;text-align:left}
.dc-menu__tile .elementor-icon{font-size:22px!important;width:44px;height:44px;display:grid!important;place-items:center;border-radius:14px;background:var(--dc-grad);color:#fff!important;box-shadow:0 8px 18px -8px rgba(178,28,44,.9)}
