.dc-menu__tile .elementor-icon-box-title{margin:0 0 .15em!important;font:800 1.15rem/1.1 "Bricolage Grotesque",sans-serif!important;color:var(--dc-cream)!important}
.dc-menu__tile .elementor-icon-box-title a{color:inherit!important}
.dc-menu__tile .elementor-icon-box-description{margin:0!important;font-size:.8rem!important;line-height:1.3;color:var(--dc-muted)!important}
/* menú principal */
.dc-menu__nav .elementor-nav-menu--main{counter-reset:dcm}
.dc-menu__nav .elementor-nav-menu>li{counter-increment:dcm;border-bottom:1px dashed var(--dc-line)}
.dc-menu__nav .elementor-nav-menu>li>a.elementor-item{display:flex!important;align-items:baseline;justify-content:flex-start!important;gap:.4em;padding:.62em 0!important;font:800 1.6rem/1.1 "Bricolage Grotesque",sans-serif!important;color:var(--dc-cream)!important;background:none!important;transition:color .2s,padding .25s}
.dc-menu__nav .elementor-nav-menu>li>a.elementor-item:before,.dc-menu__nav .elementor-nav-menu>li>a.elementor-item:after{position:static!important;inset:auto!important;transform:none!important;width:auto!important;height:auto!important;background:none!important;opacity:1!important}
.dc-menu__nav .elementor-nav-menu>li>a.elementor-item:after{display:none!important}
.dc-menu__nav .elementor-nav-menu>li>a.elementor-item:before{flex:0 0 2em;display:inline-block!important;content:"0" counter(dcm)!important;font:700 .72rem/1 "DM Sans",sans-serif;letter-spacing:.12em;color:var(--dc-amber);opacity:.8}
.dc-menu__nav .elementor-nav-menu>li>a.elementor-item:hover,.dc-menu__nav .elementor-nav-menu>li>a.elementor-item-active{padding-left:.35em!important;background:var(--dc-grad)!important;-webkit-background-clip:text!important;background-clip:text!important;color:transparent!important}
.dc-menu__nav .elementor-nav-menu>li>a.elementor-item:hover:before,.dc-menu__nav .elementor-nav-menu>li>a.elementor-item-active:before{color:var(--dc-amber)}
