/* tarjeta de pedido */
.dc-menu__promo{position:relative;flex-direction:row!important;align-items:center;gap:.6em!important;padding:1.1em 1.1em 1.1em .4em!important;border-radius:22px;background:linear-gradient(135deg,rgba(224,102,46,.18),rgba(122,16,34,.28))!important;border:1px solid rgba(239,165,78,.3);overflow:hidden}
