.dc-menu__foot{align-items:center;justify-content:space-between;padding-top:1.1em!important;border-top:1px solid var(--dc-line)}
.dc-menu__social{width:auto!important}
.dc-menu__social .elementor-social-icon{width:40px;height:40px;font-size:16px!important;padding:0!important;display:inline-grid!important;place-items:center;background:rgba(255,255,255,.06)!important;border:1px solid var(--dc-line);transition:transform .2s,background .2s}
