/* ===== Mi cuenta (página 11) ===== */
.dc-accpage{padding-top:2.4em!important}
.dc-account .woocommerce-MyAccount-navigation ul{display:flex!important;flex-wrap:wrap;gap:.45em;margin:0 0 1.4em!important;padding:0!important;list-style:none;border:0!important}
.dc-account .woocommerce-MyAccount-navigation li{margin:0!important;border:0!important;background:none!important}
.dc-account .woocommerce-MyAccount-navigation li a{display:block;padding:.65em 1.1em!important;border-radius:999px!important;background:rgba(255,255,255,.05)!important;border:1px solid var(--dc-line)!important;color:var(--dc-txt)!important;font:600 .92rem/1 "DM Sans",sans-serif!important;text-decoration:none!important;transition:border-color .2s,background .2s}
.dc-account .woocommerce-MyAccount-navigation li a:hover{border-color:rgba(239,165,78,.55)!important}
.dc-account .woocommerce-MyAccount-navigation li.is-active a{background:var(--dc-grad)!important;border-color:transparent!important;color:#fff!important}
.dc-account .woocommerce-MyAccount-navigation-link--downloads{display:none!important}
.dc-account .woocommerce-MyAccount-content,.dc-account .e-my-account-tab__content,.dc-account .woocommerce-form-login,.dc-account .woocommerce-form-register{background:linear-gradient(160deg,rgba(255,255,255,.05),rgba(255,255,255,.015))!important;border:1px solid var(--dc-line)!important;border-radius:var(--dc-r)!important;padding:1.4em!important;color:var(--dc-txt)!important;width:100%!important;float:none!important}
.dc-account p,.dc-account address,.dc-account mark{color:var(--dc-txt)!important;background:none!important}
.dc-account mark{color:var(--dc-amber)!important;font-weight:700}
.dc-account a{color:var(--dc-amber)!important}
.dc-account h2,.dc-account h3,.dc-account legend{font:800 1.3rem/1.15 "Bricolage Grotesque",sans-serif!important;color:var(--dc-cream)!important}
.dc-account table.shop_table,.dc-account table.shop_table td,.dc-account table.shop_table th{background:transparent!important;border-color:var(--dc-line)!important;color:var(--dc-txt)!important}
.dc-account table.shop_table thead th{font:700 .72rem/1 "DM Sans",sans-serif!important;letter-spacing:.14em;text-transform:uppercase;color:var(--dc-amber)!important}
.dc-account table.shop_table tr:hover td{background:rgba(255,255,255,.025)!important}
.dc-account .woocommerce-orders-table__cell-order-number a{font-weight:800;color:var(--dc-cream)!important}
.dc-account .amount{color:var(--dc-amber)!important;font-weight:800}
.dc-account .button,.dc-account button.button,.dc-account .woocommerce-button{display:inline-flex!important;align-items:center;justify-content:center;border-radius:999px!important;background:rgba(255,255,255,.06)!important;color:var(--dc-cream)!important;border:1px solid rgba(239,165,78,.45)!important;font:700 .88rem/1 "DM Sans",sans-serif!important;padding:.7em 1.1em!important;margin:.15em .2em .15em 0!important;text-decoration:none!important}
.dc-account .button:hover{border-color:var(--dc-amber)!important;background:rgba(239,165,78,.12)!important}
.dc-account .order-again .button,.dc-account .woocommerce-form-login__submit,.dc-account .woocommerce-Button[name=save_account_details],.dc-account button[name=save_address],.dc-account .woocommerce-form-register__submit{background:var(--dc-grad)!important;border:0!important;color:#fff!important;padding:.9em 1.5em!important}
.dc-account input.input-text,.dc-account textarea,.dc-account select,.dc-account .select2-container .select2-selection{background:#120d0a!important;border:1px solid var(--dc-line)!important;color:var(--dc-cream)!important;border-radius:12px!important;min-height:3em;padding:.6em 1em!important}
.dc-account input.input-text:focus{border-color:var(--dc-amber)!important;outline:0}
.dc-account label{color:var(--dc-txt)!important;font-weight:600}
.dc-account .woocommerce-Addresses{display:grid!important;grid-template-columns:1fr 1fr;gap:1em}
.dc-account .woocommerce-Address{width:auto!important;float:none!important;padding:1.1em;border:1px dashed var(--dc-line);border-radius:14px}
.dc-account .woocommerce-info,.dc-account .woocommerce-message{background:var(--dc-s2)!important;color:var(--dc-txt)!important;border-top-color:var(--dc-fire)!important;border-radius:12px}
.dc-account .woocommerce-pagination .button{background:rgba(255,255,255,.06)!important}
.dc-account .order-status,.dc-account .woocommerce-orders-table__cell-order-status{color:var(--dc-cream)!important;font-weight:700}
@media(max-width:767px){.dc-account .woocommerce-Addresses{grid-template-columns:1fr}.dc-account .woocommerce-MyAccount-navigation ul{flex-wrap:nowrap;overflow-x:auto;padding-bottom:.3em!important}.dc-account .woocommerce-MyAccount-navigation li a{white-space:nowrap}.dc-account table.shop_table_responsive tr{display:block;margin:0 0 1em;border:1px solid var(--dc-line);border-radius:14px;padding:.4em .8em}.dc-account table.shop_table_responsive tr td{border:0!important}}
/* contraste carrito/checkout (textos que Elementor pinta oscuros) */
.dc-cart,.dc-checkout{--sections-title-color:var(--dc-cream);--sections-descriptions-color:var(--dc-txt);--sections-background-color:transparent;--sections-border-color:var(--dc-line);--forms-fields-normal-color:var(--dc-cream);--forms-fields-normal-background-color:#120d0a;--forms-fields-border-color:var(--dc-line);--forms-labels-color:var(--dc-txt);--order-summary-items-color:var(--dc-txt);--order-summary-totals-color:var(--dc-txt);--order-summary-variations-color:var(--dc-muted);--totals-color:var(--dc-txt);--product-link-normal-color:var(--dc-cream);--product-price-color:var(--dc-amber);--product-variations-color:var(--dc-muted);--typography-section-titles-color:var(--dc-cream);--links-normal-color:var(--dc-amber);color:var(--dc-txt)}
.dc-cart dl.variation,.dc-cart dl.variation dt,.dc-cart dl.variation dd,.dc-cart dl.variation p,.dc-cart .wc-item-meta,.dc-cart .wc-item-meta *,.dc-checkout dl.variation,.dc-checkout dl.variation *,.dc-checkout .wc-item-meta *{color:var(--dc-muted)!important;font-size:.88rem}
.dc-cart dl.variation dt,.dc-checkout dl.variation dt{color:var(--dc-txt)!important;font-weight:700}
.dc-cart .e-cart-section,.dc-cart .cart_totals{color:var(--dc-txt)!important}
.dc-cart .cart_totals h2,.dc-cart .e-cart-totals h2,.dc-cart .e-cart-section h2,.dc-cart .cart_totals>h2{color:var(--dc-cream)!important}
.dc-cart .cart_totals th,.dc-cart .cart_totals td,.dc-cart .cart_totals td *{color:var(--dc-txt)!important}
.dc-cart .cart_totals .amount,.dc-cart .cart_totals .amount *{color:var(--dc-amber)!important}
.dc-cart .woocommerce-Price-currencySymbol,.dc-checkout .woocommerce-Price-currencySymbol{color:inherit!important}
.dc-cart .amount bdi,.dc-checkout .amount bdi{color:var(--dc-amber)!important}
.dc-cart .e-cart-totals.e-cart-section{border:0!important;background:none!important;padding:0!important}
.dc-cart .quantity input.qty,.dc-checkout input.qty{color:var(--dc-cream)!important;background:rgba(255,255,255,.06)!important;border:1px solid var(--dc-line)!important;border-radius:999px!important;-webkit-text-fill-color:var(--dc-cream)}
.dc-checkout,.dc-checkout td,.dc-checkout th,.dc-checkout p,.dc-checkout span:not(.amount):not(.required),.dc-checkout li,.dc-checkout strong{color:var(--dc-txt)}
.dc-checkout .product-name,.dc-checkout .cart_item td{color:var(--dc-cream)!important}
.dc-checkout input.input-text,.dc-checkout textarea{-webkit-text-fill-color:var(--dc-cream)}
.dc-checkout ::placeholder,.dc-cart ::placeholder,.dc-account ::placeholder{color:rgba(233,220,205,.45)!important}
.dc-checkout #payment,.dc-checkout #payment *{color:var(--dc-txt)}
.dc-checkout #payment label{color:var(--dc-cream)!important}
.dc-checkout .woocommerce-shipping-methods label,.dc-checkout .wc_payment_method label{color:var(--dc-cream)!important}
/* ===== Footer compacto ===== */
.dc-foot{padding:2.6em 0 1.4em!important;background:linear-gradient(180deg,rgba(0,0,0,0),rgba(0,0,0,.45))!important;border-top:1px solid var(--dc-line)}
.dc-foot__top{justify-content:space-between;align-items:flex-start;gap:1.6em 3em!important;padding-bottom:1.6em!important}
.dc-foot__brand{flex:1 1 300px;max-width:440px;gap:.8em!important}
.dc-foot__logo{width:auto!important}
.dc-foot__logo img{width:70px!important;height:auto}
.dc-foot__tag p{margin:0;color:var(--dc-muted);font-size:.95rem;line-height:1.55}
.dc-foot__tag strong{color:var(--dc-amber)}
.dc-foot__social{width:auto!important}
.dc-foot__social .elementor-grid{display:flex!important;gap:.5em!important}
.dc-foot__social .elementor-social-icon{width:40px;height:40px;font-size:16px!important;padding:0!important;display:inline-grid!important;place-items:center;background:rgba(255,255,255,.06)!important;border:1px solid var(--dc-line);transition:transform .2s,background .2s}
.dc-foot__social .elementor-social-icon:hover{transform:translateY(-2px);background:var(--dc-grad)!important;border-color:transparent}
.dc-foot__social .elementor-social-icon i,.dc-foot__social .elementor-social-icon svg{color:var(--dc-cream)!important;fill:var(--dc-cream)!important}
.dc-foot__col{flex:0 1 auto;gap:.2em!important}
.dc-foot__col .dc-eyebrow p{margin:0 0 .5em!important}
.dc-foot__tels .elementor-icon-list-item{padding:.3em 0!important}
.dc-foot__tels .elementor-icon-list-item a{display:flex;align-items:center}
.dc-foot__tels .elementor-icon-list-icon{width:1.3em!important;margin-right:.55em!important;padding:0!important}
.dc-foot__tels .elementor-icon-list-icon i{color:var(--dc-amber)!important;font-size:.9em}
.dc-foot__tels .elementor-icon-list-text{color:var(--dc-muted)!important;font-size:.92rem;padding:0!important}
.dc-foot__tels .elementor-icon-list-text b{color:var(--dc-cream);font-weight:700;margin-left:.25em}
.dc-foot__tels a:hover .elementor-icon-list-text b{color:var(--dc-amber)}
.dc-foot__bottom{justify-content:space-between;align-items:center;gap:.6em 1.4em!important;padding-top:1.1em!important;border-top:1px dashed var(--dc-line)}
.dc-foot__legal{width:auto!important}
.dc-foot__legal .elementor-nav-menu{display:flex!important;flex-wrap:wrap;gap:.2em 1.1em}
.dc-foot__legal .elementor-nav-menu a.elementor-item{padding:.2em 0!important;color:var(--dc-muted)!important;font:500 .82rem/1.2 "DM Sans",sans-serif!important;background:none!important}
.dc-foot__legal .elementor-nav-menu a.elementor-item:hover{color:var(--dc-amber)!important}
.dc-foot__legal .elementor-menu-toggle{display:none!important}
.dc-foot__credit .elementor-heading-title{margin:0;font:400 .8rem/1.4 "DM Sans",sans-serif!important;color:rgba(191,174,159,.7)!important}
.dc-foot__credit a{color:var(--dc-muted)!important}
@media(max-width:767px){.dc-foot{padding:2em 0 1em!important}.dc-foot__top{gap:1.4em!important}.dc-foot__bottom{flex-direction:column!important;align-items:flex-start}}
/* ===== Carrito lateral (menu cart 1eb11b7) ===== */
.elementor-menu-cart__container{background:rgba(8,5,4,.72)!important;-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px)}
.elementor-menu-cart__container .elementor-menu-cart__main{width:min(94vw,420px)!important;max-width:none!important;padding:1.4em 1.4em 1.2em!important;background:radial-gradient(380px 260px at 100% 105%,rgba(224,102,46,.22),transparent 65%),linear-gradient(180deg,#1E1210,#120b09)!important;border-left:1px solid rgba(239,165,78,.18)!important;border-radius:26px 0 0 26px;box-shadow:-30px 0 80px -20px rgba(0,0,0,.95)!important;display:flex;flex-direction:column}
.elementor-menu-cart__main:before{content:"Tu pedido";display:block;margin:.2em 0 .9em;padding-right:3em;font:800 1.6rem/1.1 "Bricolage Grotesque",sans-serif;color:var(--dc-cream)}
.elementor-menu-cart__close-button{top:1.2em!important;right:1.2em!important;width:42px!important;height:42px!important;margin:0!important;border-radius:50%;background:rgba(255,255,255,.06);border:1px solid var(--dc-line);position:absolute!important;transition:transform .25s,background .25s}
.elementor-menu-cart__close-button:hover{transform:rotate(90deg);background:rgba(224,102,46,.2)}
.elementor-menu-cart__close-button:before,.elementor-menu-cart__close-button:after{width:16px!important;left:12px!important;top:19px!important;height:2px!important;background:var(--dc-cream)!important}
.elementor-menu-cart__main .widget_shopping_cart_content{display:flex;flex-direction:column;flex:1 1 auto;min-height:0}
.elementor-menu-cart__products{flex:1 1 auto;overflow-y:auto;margin:0 -.3em!important;padding:0 .3em!important}
.elementor-menu-cart__product{display:grid!important;grid-template-columns:64px 1fr auto!important;grid-template-rows:auto auto;column-gap:.85em!important;row-gap:.15em;align-items:center;padding:.85em!important;margin:0 0 .6em!important;border:1px solid var(--dc-line)!important;border-radius:16px;background:rgba(255,255,255,.03)}
.elementor-menu-cart__product-image{grid-row:1/3;grid-column:1;width:64px!important}
.elementor-menu-cart__product-image img{width:64px!important;height:64px!important;object-fit:cover;border-radius:12px}
.elementor-menu-cart__product-name{grid-column:2;grid-row:1;margin:0!important;padding:0!important}
.elementor-menu-cart__product-name a{font:800 1rem/1.2 "Bricolage Grotesque",sans-serif!important;color:var(--dc-cream)!important;text-decoration:none!important}
.elementor-menu-cart__product-name dl.variation,.elementor-menu-cart__product-name dl.variation *{margin:0!important;font-size:.78rem!important;color:var(--dc-muted)!important;line-height:1.35}
.elementor-menu-cart__product-price{grid-column:2;grid-row:2;margin:0!important;padding:0!important;color:var(--dc-muted)!important;font-size:.88rem}
.elementor-menu-cart__product-price .amount,.elementor-menu-cart__product-price .amount *{color:var(--dc-amber)!important;font-weight:800}
.elementor-menu-cart__product-remove{grid-column:3;grid-row:1/3;position:static!important;width:30px!important;height:30px!important;border-radius:50%;border:1px solid var(--dc-line)!important;background:rgba(255,255,255,.04);margin:0!important}
.elementor-menu-cart__product-remove:hover{background:var(--dc-fire);border-color:var(--dc-fire)!important}
.elementor-menu-cart__product-remove:before,.elementor-menu-cart__product-remove:after{background:var(--dc-cream)!important;width:12px!important;left:8px!important;top:13px!important}
.elementor-menu-cart__subtotal{display:flex!important;justify-content:space-between;align-items:baseline;margin:.6em 0 .9em!important;padding:1em 0 0!important;border-top:1px dashed var(--dc-line)!important;border-bottom:0!important;font:700 1rem/1 "DM Sans",sans-serif!important;color:var(--dc-txt)!important;text-align:left!important}
.elementor-menu-cart__subtotal strong{color:var(--dc-txt)!important;font-weight:700}
.elementor-menu-cart__subtotal .amount,.elementor-menu-cart__subtotal .amount *{font:800 1.5rem/1 "DM Sans",sans-serif!important;color:var(--dc-amber)!important}
.elementor-menu-cart__footer-buttons{display:grid!important;grid-template-columns:1fr!important;gap:.55em!important;margin:0!important;padding:0!important}
.elementor-menu-cart__footer-buttons .elementor-button{width:100%;justify-content:center;padding:1em 1.2em!important;font:800 1rem/1 "DM Sans",sans-serif!important;border-radius:999px!important}
.elementor-menu-cart__footer-buttons .elementor-button--checkout{order:-1;box-shadow:var(--dc-shadow)}
.elementor-menu-cart__footer-buttons .elementor-button--view-cart{font-weight:700!important}
.elementor-menu-cart__main .woocommerce-mini-cart__empty-message{margin:auto 0;padding:2.4em 1em;text-align:center;color:var(--dc-muted)!important;font-size:1rem;border:1px dashed var(--dc-line);border-radius:18px}
.elementor-menu-cart__main .woocommerce-mini-cart__empty-message:before{content:"🍕";display:block;font-size:2.4rem;margin-bottom:.4em}
@media(max-width:767px){.elementor-menu-cart__container .elementor-menu-cart__main{border-radius:22px 0 0 22px;padding:1.2em 1em 1em!important}}
